using Microsoft.Extensions.ML;
using Microsoft.ML;
using ChurnPredictor;

var builder = WebApplication.CreateBuilder(args);

var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");

builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelName: null, filePath: modelPath, watchForChanges: true);

var app = builder.Build();

// Train model on startup if it doesn't exist
if (!File.Exists(modelPath))
{
    var logger = app.Services.GetRequiredService<ILogger<ChurnModelTrainer>>();
    var trainer = new ChurnModelTrainer(dataPath, modelPath, logger);
    trainer.Train();
}

app.MapGet("/", () => "Hello");

app.MapGet("/train", (ILogger<ChurnModelTrainer> logger) =>
{
    var trainer = new ChurnModelTrainer(dataPath, modelPath, logger);
    trainer.Train();
    return Results.Ok("Model trained successfully.");
});

app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        prediction.PredictedLabel,
        prediction.Probability,
        prediction.Score
    });
});

app.Run();

